import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarTemperatura } from './solution.mjs';

test('fahrenheit calcula a conversão de celsius na hora', () => {
  const t = criarTemperatura(0);
  assert.equal(t.fahrenheit, 32);
});

test('setter de fahrenheit converte e guarda em celsius', () => {
  const t = criarTemperatura(0);
  t.fahrenheit = 212;
  assert.equal(t.celsius, 100);
});

test('celsius mudado reflete no fahrenheit calculado', () => {
  const t = criarTemperatura(0);
  t.celsius = 50;
  assert.equal(t.fahrenheit, 122);
});

test('round-trip: 32°F volta para 0°C', () => {
  const t = criarTemperatura(100);
  t.fahrenheit = 32;
  assert.equal(t.celsius, 0);
});

solutionCode:
export function criarTemperatura(celsius) {
  return {
    _celsius: celsius,
    get celsius() {
      return this._celsius;
    },
    set celsius(valor) {
      this._celsius = valor;
    },
    get fahrenheit() {
      return this._celsius * 9 / 5 + 32;
    },
    set fahrenheit(valor) {
      this._celsius = (valor - 32) * 5 / 9;
    }
  };
}
